        if ( b == 0 ) { return 0; } if ( b < 128 ) { continue; }
        if ( b >= 194 && b <= 223 ) { cp = b & 31; more = 1; }
        else if ( b >= 224 && b <= 239 ) { cp = b & 15; more = 2; }
        else if ( b >= 240 && b <= 244 ) { cp = b & 7; more = 3; }
        else { return 0; }
