 *lo=*hi=0;
 if(width<0 || width>128 || !blockdemo_table_bit_get(&r->bits,lo,width<64?width:64))return 0;
 if(width>64 && !blockdemo_table_bit_get(&r->bits,hi,width-64))return 0;
